/* Account-isolated workspace synchronization. Only a publishable key is used. */
const cloud={client:window.formaSupabase,user:null,revision:0,ready:false,dirty:false,busy:false,conflict:false,status:'Local only',error:'',generation:0,sequence:0,timer:null,google:false,starting:true,loading:false};
const beforeCloudRender=render;
render=function(){if(typeof canUseForma!=='function'||canUseForma())beforeCloudRender();updateCloudUI()};
function accountCacheKey(id){return 'forma.account.'+id}
function readAccountCache(id){try{return JSON.parse(localStorage.getItem(accountCacheKey(id))||'null')}catch{return null}}
function cacheWorkspace(){try{if(cloud.user)localStorage.setItem(accountCacheKey(cloud.user.id),JSON.stringify({document:state,revision:cloud.revision,dirty:cloud.dirty}));else localStorage.setItem(KEY,JSON.stringify(state));return true}catch{cloud.error='Browser storage is full. Export a backup before closing.';toast(cloud.error);return false}}
save=function(){if(typeof canUseForma==='function'&&!canUseForma())return;cloud.sequence++;if(cloud.user)cloud.dirty=true;cacheWorkspace();queueCloudSave();updateCloudUI()};
function queueCloudSave(){if(!cloud.user||!cloud.ready||cloud.conflict)return;cloud.dirty=true;clearTimeout(cloud.timer);cloud.timer=setTimeout(()=>syncCloud(),1800);updateCloudUI()}
function cloudLabel(){return cloud.starting?'Checking account…':!cloud.user?'Local only':cloud.conflict?'Sync conflict':!cloud.ready?'Account setup needed':cloud.busy?'Saving…':cloud.dirty?'Changes on this device':cloud.error?'Sync needs attention':'Cloud saved'}
function updateCloudUI(){let button=$('#account-button');if(!button){button=document.createElement('button');button.id='account-button';button.className='btn soft small';button.onclick=()=>openAccount();$('.header-right')?.prepend(button)}if(button){button.textContent=cloud.user?'Account':'Sign in';button.disabled=cloud.starting}let indicator=$('.local-indicator');if(indicator)indicator.textContent='● '+cloudLabel();let note=$('.side-bottom p');if(note)note.textContent=cloud.user?cloud.user.email:'Your entries stay in this browser.';let foot=$('footer span');if(foot)foot.textContent=cloud.user?'Private account · '+cloudLabel():'Browser storage · Sign in for cloud saving';let preview=$('.preview');if(preview)preview.textContent=cloud.user?'PRIVATE ACCOUNT':'LOCAL WORKSPACE';let label=$('#profile-storage-label');if(label)label.textContent=cloud.user?'PRIVATE ACCOUNT':'LOCAL PROFILE';let status=$('#cloud-live-status');if(status)status.textContent=cloudLabel()+(cloud.error?' · '+cloud.error:'');if(typeof renderAuthGate==='function')renderAuthGate()}
function localGuestData(){try{let d=JSON.parse(localStorage.getItem(KEY)||'null');return d&&validBackup(d)?d:null}catch{return null}}
function hasWorkspaceData(d){return !!d&&(d.profile?.onboarded||['sessions','meals','weights','checkins','products'].some(k=>d[k]?.length)||d.routines?.length)}
async function handleCloudSession(session){const user=session?.user;if(cloud.user?.id===user?.id&&!cloud.starting)return;const generation=++cloud.generation;clearTimeout(cloud.timer);cloud.ready=false;cloud.dirty=false;cloud.conflict=false;cloud.error='';cloud.busy=false;cloud.user=user||null;cloud.starting=false;cloud.loading=!!user;if(!user){state=defaults();cloud.revision=0;render();return}state=defaults();render();try{const cache=readAccountCache(user.id);const {data,error}=await cloud.client.from('forma_workspaces').select('payload,revision,updated_at').eq('user_id',user.id).maybeSingle();if(generation!==cloud.generation)return;if(error)throw error;cloud.loading=false;if(data){if(!validBackup(data.payload))throw Error('Cloud workspace format is not supported. Export local data and contact support.');cloud.revision=Number(data.revision);if(cache?.dirty&&validBackup(cache.document)){state=cache.document;cloud.dirty=true;if(cache.revision!==cloud.revision){cloud.conflict=true;cloud.error='This device has unsaved changes and the cloud has a newer revision.'}else cloud.ready=true}else{state=data.payload;cloud.ready=true}cacheWorkspace();render();if(cloud.dirty&&!cloud.conflict)queueCloudSave()}else if(cache?.dirty&&validBackup(cache.document)){state=cache.document;cloud.revision=0;cloud.ready=true;cloud.dirty=true;render();queueCloudSave()}else{cloud.revision=0;render();openMigration()}}catch(error){if(generation!==cloud.generation)return;cloud.loading=false;cloud.error=error.message||'Could not load your account';let cache=readAccountCache(user.id);if(cache&&validBackup(cache.document)){state=cache.document;cloud.revision=cache.revision;cloud.dirty=!!cache.dirty}render();toast('Could not load cloud data. Your local copy is preserved.')}}
async function syncCloud(){if(!cloud.user||!cloud.ready||cloud.conflict)return false;if(cloud.busy)return false;cloud.busy=true;cloud.error='';updateCloudUI();const generation=cloud.generation,sequence=cloud.sequence,document=structuredClone(state),revision=cloud.revision;try{const {data,error}=await cloud.client.rpc('forma_save_workspace',{document,expected_revision:revision});if(generation!==cloud.generation)return false;if(error){if(error.code==='40001')cloud.conflict=true;throw error}if(!data?.[0]?.saved_revision)throw Error('The server did not confirm the save.');cloud.revision=Number(data[0].saved_revision);cloud.dirty=cloud.sequence!==sequence;cacheWorkspace();return true}catch(error){if(generation===cloud.generation){cloud.error=error.message||'Cloud save failed';cloud.dirty=true;cacheWorkspace()}return false}finally{if(generation===cloud.generation){cloud.busy=false;updateCloudUI();if(cloud.dirty&&!cloud.error)queueCloudSave()}}}
function openMigration(){if(typeof renderMigrationScreen==='function')renderMigrationScreen()}
async function beginCloudWorkspace(useGuest){if(!cloud.user)return;let d=useGuest?localGuestData():defaults();if(!d){toast('No compatible browser data found');return}state=structuredClone(d);cloud.loading=false;cloud.ready=true;cloud.dirty=true;cloud.sequence++;cacheWorkspace();closeModal();render();let ok=await syncCloud();if(ok){if(useGuest){try{localStorage.removeItem(KEY)}catch{}}toast('Your private workspace is saved')}else{toast('Saved locally; cloud upload needs attention');openAccount()}}
function exportGuestBackup(){let guest=localGuestData();if(!guest){toast('No browser backup to export');return}downloadWorkspace(guest,'forma-browser-backup')}
function downloadWorkspace(doc,name){let url=URL.createObjectURL(new Blob([JSON.stringify(doc,null,2)],{type:'application/json'}));let link=document.createElement('a');link.href=url;link.download=name+'-'+today()+'.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function openAccount(mode='signin'){if(cloud.user){modal(modalHead('Your account')+`<p class="small-muted">${esc(cloud.user.email)}</p><div class="section-note" id="cloud-live-status">${esc(cloudLabel())}${cloud.error?' · '+esc(cloud.error):''}</div><div class="actions">${!cloud.ready&&!cloud.conflict?'<button class="btn" onclick="openMigration()">Set up workspace</button>':''}<button class="btn secondary" onclick="exportData()">Download backup</button>${cloud.ready&&!cloud.conflict?'<button class="btn" onclick="manualCloudSync()">Sync now</button>':''}${cloud.conflict?'<button class="btn" onclick="reviewCloudConflict()">Resolve conflict</button>':''}<button class="btn secondary" onclick="signOutForma()">Sign out</button></div>`);return}modal(modalHead(mode==='signup'?'Create your My Fitness Diary account':'Welcome back')+`<p class="small-muted">Your own workouts, nutrition, and progress—saved across devices.</p><div class="tabs"><button class="tab ${mode==='signin'?'active':''}" onclick="openAccount('signin')">Sign in</button><button class="tab ${mode==='signup'?'active':''}" onclick="openAccount('signup')">Create account</button></div><form id="auth-form" onsubmit="submitAccount(event,'${mode}')"><label for="auth-email">Email</label><input id="auth-email" type="email" required autocomplete="email" maxlength="254"><label for="auth-password">Password</label><input id="auth-password" type="password" required minlength="12" autocomplete="${mode==='signup'?'new-password':'current-password'}">${mode==='signup'?'<p class="small-muted">Use at least 12 characters. Confirm your email before signing in.</p>':''}<div id="auth-error" class="auth-error" role="status"></div><button id="auth-submit" class="btn full">${mode==='signup'?'Create account':'Sign in'}</button></form><div class="auth-divider">or</div><button type="button" id="google-signin-button" class="btn secondary full">Continue with Google</button><div id="google-auth-status" class="auth-error" role="status" aria-live="polite"></div>`);$('#google-signin-button').addEventListener('click',googleSignIn)}
async function submitAccount(event,mode){event.preventDefault();let email=$('#auth-email').value.trim(),password=$('#auth-password').value,button=$('#auth-submit');button.disabled=true;$('#auth-error').textContent='';try{let result=mode==='signup'?await cloud.client.auth.signUp({email,password,options:{emailRedirectTo:location.origin+location.pathname}}):await cloud.client.auth.signInWithPassword({email,password});if(result.error)throw result.error;$('#auth-password')&&($('#auth-password').value='');if(mode==='signup'&&!result.data.session){$('#auth-error').textContent='Check your inbox to confirm your email, then return and sign in.';return}closeModal();await handleCloudSession(result.data.session);toast('Signed in')}catch(error){let target=$('#auth-error');if(target)target.textContent=error.message||'Could not sign in'}finally{if($('#auth-submit'))$('#auth-submit').disabled=false}}
async function googleSignIn(){let button=$('#google-signin-button'),status=$('#google-auth-status');if(button?.disabled)return;let waiting;if(button){button.disabled=true;button.textContent='Connecting to Google…'}if(status)status.textContent='Preparing secure sign-in…';try{if(!cloud.client?.auth)throw Error('Account services did not load. Refresh the page and try again.');const result=await Promise.race([cloud.client.auth.signInWithOAuth({provider:'google',options:{redirectTo:location.origin+location.pathname,skipBrowserRedirect:true}}),new Promise((_,reject)=>{waiting=setTimeout(()=>reject(Error('Sign-in timed out. Refresh this page and try again.')),12000)})]);clearTimeout(waiting);if(result.error)throw result.error;if(!result.data?.url)throw Error('No sign-in link was returned.');let url=new URL(result.data.url);if(url.protocol!=='https:'||url.hostname!=='djyozltkmbzhwuvemxuy.supabase.co')throw Error('Unexpected sign-in destination.');if(status){status.textContent='Opening Google sign-in… ';let link=document.createElement('a');link.href=url.href;link.textContent='Click here if you are not redirected';link.target='_self';link.className='text-btn';status.appendChild(link)}window.location.assign(url.href)}catch(error){clearTimeout(waiting);let message=error.message||'Google sign-in could not start.';if(status)status.textContent=message;toast(message)}finally{if(button){button.disabled=false;button.textContent='Continue with Google'}}}

async function manualCloudSync(){if(!cloud.dirty){await refreshCloud();openAccount();return}await syncCloud();openAccount()}
async function refreshCloud(){if(!cloud.user||!cloud.ready||cloud.dirty||cloud.busy)return;let generation=cloud.generation;try{const {data,error}=await cloud.client.from('forma_workspaces').select('payload,revision').eq('user_id',cloud.user.id).maybeSingle();if(generation!==cloud.generation)return;if(error)throw error;if(data&&Number(data.revision)>cloud.revision){if(!validBackup(data.payload))throw Error('Unsupported workspace format');state=data.payload;cloud.revision=Number(data.revision);cacheWorkspace();render()}cloud.error=''}catch(error){cloud.error=error.message}updateCloudUI()}
function reviewCloudConflict(){modal(modalHead('Keep your changes safe')+`<p class="small-muted">Another device saved a newer workspace. My Fitness Diary stopped automatic saving to prevent overwriting it.</p><p class="small-muted">Export this device’s changes first. Reloading replaces this view with the saved cloud copy; it does not merge the two histories.</p><div class="actions"><button class="btn secondary" onclick="exportData()">Export this device</button><button class="btn" onclick="reloadCloudConfirmed()">Discard local changes & reload cloud</button><button class="btn secondary" onclick="closeModal()">Keep working locally</button></div>`)}
async function reloadCloudConfirmed(){if(!cloud.user)return;let id=cloud.user.id;try{localStorage.setItem(accountCacheKey(id)+'.recovery',JSON.stringify({document:state,revision:cloud.revision,dirty:cloud.dirty}));localStorage.removeItem(accountCacheKey(id))}catch{toast('Export your backup before reloading');return}let session=(await cloud.client.auth.getSession()).data.session;cloud.user=null;closeModal();await handleCloudSession(session)}
async function signOutForma(){if(cloud.busy){toast('Wait for the current save before signing out');return}if(cloud.dirty){modal(modalHead('Changes are still on this device')+'<p class="small-muted">Export a backup or try syncing. Your account-specific local copy will remain available when you sign in again on this browser.</p><div class="actions"><button class="btn secondary" onclick="exportData()">Export backup</button><button class="btn secondary" onclick="manualCloudSync()">Try sync</button><button class="btn danger" onclick="performFormaSignOut()">Sign out anyway</button></div>');return}await performFormaSignOut()}
async function performFormaSignOut(){cacheWorkspace();const {error}=await cloud.client.auth.signOut({scope:'local'});if(error){toast(error.message);return}closeModal();await handleCloudSession(null);state=defaults();render();toast('Signed out on this device')}
async function initializeCloud(){if(!cloud.client){cloud.starting=false;cloud.error='Sign-in is temporarily unavailable. Please refresh and try again.';updateCloudUI();return}cloud.client.auth.onAuthStateChange((event,session)=>{if(event==='INITIAL_SESSION')return;if(['SIGNED_IN','SIGNED_OUT','TOKEN_REFRESHED'].includes(event))setTimeout(()=>handleCloudSession(session),0)});try{const {data,error}=await cloud.client.auth.getSession();if(error)throw error;if(data.session){const verified=await cloud.client.auth.getUser();if(verified.error)throw verified.error;await handleCloudSession({...data.session,user:verified.data.user})}else{cloud.starting=false;updateCloudUI()}}catch(error){cloud.starting=false;cloud.error=error.message;updateCloudUI()}}

window.addEventListener('focus',()=>refreshCloud());window.addEventListener('online',()=>{if(cloud.dirty)syncCloud();else refreshCloud()});window.addEventListener('beforeunload',event=>{if(cloud.user&&cloud.dirty){cacheWorkspace();event.preventDefault();event.returnValue=''}});
initializeCloud();
const oauthErrorParams=new URLSearchParams(location.search);if(oauthErrorParams.has('error_description')){setTimeout(()=>{openAccount();const el=$('#google-auth-status');if(el)el.textContent=oauthErrorParams.get('error_description')},300)}

function resetModal(){if(!cloud.user){localResetModal();return}modal(modalHead('Your cloud workspace is connected')+'<p class="small-muted">Local reset is unavailable while signed in, so it cannot accidentally erase your cloud history. Export a backup before making bulk changes.</p><div class="actions"><button class="btn secondary" onclick="exportData()">Export backup</button><button class="btn" onclick="closeModal()">Keep my workspace</button></div>')}
